/** The entity {@code msm_test:tb_tame_first} (base animal), animated with GeckoLib. */
public class TbTameFirstEntity extends TamableAnimal implements GeoEntity {
    private static final Predicate<ItemStack> TAMING_FOOD = ofItems("minecraft:bone");
    private static final Predicate<ItemStack> BREEDING_FOOD = ofItems("minecraft:wheat");

    private final AnimatableInstanceCache cache = GeckoLibUtil.createInstanceCache(this);

    public TbTameFirstEntity(EntityType<? extends TamableAnimal> type, Level level) {
        super(type, level);
    }

    /** The default attributes (msm:health, msm:movement, msm:attack). */
    public static AttributeSupplier.Builder createAttributes() {
        return Mob.createMobAttributes()
                .add(Attributes.MAX_HEALTH, 20.0f)
                .add(Attributes.MOVEMENT_SPEED, 0.25f)
                .add(Attributes.FOLLOW_RANGE, 16.0f)
                .add(Attributes.KNOCKBACK_RESISTANCE, 0.0f)
                .add(Attributes.ATTACK_DAMAGE, 0.0)
                .add(Attributes.ATTACK_KNOCKBACK, 0.0)
                .add(Attributes.TEMPT_RANGE, 10.0f);
    }

    /** Matches stacks of the listed items; an entry starting with {@code #} is an item tag (as msm_runtime's MobGoals.ofItems). */
    private static Predicate<ItemStack> ofItems(String... items) {
        Set<Identifier> ids = new HashSet<>();
        List<TagKey<Item>> tags = new ArrayList<>();
        for (String entry : items) {
            if (entry.startsWith("#")) {
                tags.add(TagKey.create(Registries.ITEM, Identifier.parse(entry.substring(1))));
            } else {
                ids.add(Identifier.parse(entry));
            }
        }
        return stack -> !stack.isEmpty() && (ids.contains(BuiltInRegistries.ITEM.getKey(stack.getItem()))
                || tags.stream().anyMatch(stack::is));
    }

    @Override
    protected void registerGoals() {
        goalSelector.addGoal(0, new FloatGoal(this));
        targetSelector.addGoal(0, new OwnerHurtByTargetGoal(this));
        targetSelector.addGoal(1, new OwnerHurtTargetGoal(this));
        goalSelector.addGoal(2, new BreedGoal(this, 1.0f));
        goalSelector.addGoal(3, new TemptGoal(this, 1.25f, BREEDING_FOOD, false));
        goalSelector.addGoal(4, new FollowParentGoal(this, 1.25f));
    }

    /** A right click, in the order of ADR 0071 D1: the breeding food, the taming food and the owner's sit toggle, then vanilla's. */
    @Override
    public InteractionResult mobInteract(Player player, InteractionHand hand) {
        InteractionResult result = breedingInteract(player, hand);
        if (result == null) {
            result = tamingInteract(player, hand);
        }
        if (result != null) {
            return result;
        }
        return super.mobInteract(player, hand);
    }

    /** tamed_health, healed to full. */
    private void applyTamedHealth() {
        AttributeInstance max = getAttribute(Attributes.MAX_HEALTH);
        if (max != null) {
            max.setBaseValue(30.0f);
        }
        setHealth(getMaxHealth());
    }

    /** The child getBreedOffspring made last, read back by spawnChildFromBreeding. */
    private AgeableMob lastOffspring;

    /** msm:breedable items, none while the mob is wild: an untamed pet does not breed (as wolves and cats), and vanilla's Animal.mobInteract cannot put it in love either. */
    @Override
    public boolean isFood(ItemStack stack) {
        return BREEDING_FOOD.test(stack) && isTame();
    }

    /** The breeding step of a right click: vanilla's feeding (love mode for a grown mob, growth for a baby), before msm:on_interact. A wild mob gets no love mode: its taming food passes on to taming (a shared food tames), and its breeding food only grows a baby. Null passes on. */
    private InteractionResult breedingInteract(Player player, InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        if (!BREEDING_FOOD.test(stack)) {
            return null;
        }
        boolean wild = !isTame();
        if (wild && TAMING_FOOD.test(stack)) {
            return null;
        }
        int age = getAge();
        if (!wild && player instanceof ServerPlayer && age == 0 && canFallInLove()) {
            stack.consume(1, player);
            setInLove(player);
            return InteractionResult.SUCCESS_SERVER;
        }
        if (canAgeUp()) {
            stack.consume(1, player);
            ageUp(AgeableMob.getSpeedUpSecondsWhenFeeding(-age), true);
            return InteractionResult.SUCCESS;
        }
        return level().isClientSide() && !wild ? InteractionResult.CONSUME : null;
    }

    /** A new mob of the same type (also for a spawn egg used on an adult, where the partner is this mob). */
    @Override
    public AgeableMob getBreedOffspring(ServerLevel level, AgeableMob partner) {
        AgeableMob child = getType().create(level, EntitySpawnReason.BREEDING) instanceof AgeableMob made ? made : null;
        // A tamed parent's baby belongs to the same owner, tamed (Wolf.getBreedOffspring); no sitting, hearts or on_tame.
        if (child instanceof TbTameFirstEntity baby && isTame()) {
            baby.setOwnerReference(getOwnerReference());
            baby.setTame(true, true);
            baby.applyTamedHealth();
        }
        lastOffspring = child;
        return child;
    }

    /** Vanilla's breeding (the baby, the cooldowns, hearts, experience), refused between two types and while either parent is wild (a wolf's and a cat's canMate). */
    @Override
    public void spawnChildFromBreeding(ServerLevel level, Animal partner) {
        if (partner.getType() != getType() || !isTame() || !(partner instanceof TbTameFirstEntity other && other.isTame())) {
            resetLove();
            partner.resetLove();
            return;
        }
        lastOffspring = null;
        super.spawnChildFromBreeding(level, partner);
        AgeableMob child = lastOffspring;
        lastOffspring = null;
        if (child == null || child.isRemoved() || !child.isBaby()) {
            return;
        }
    }

    /** baby_scale for a baby (also its hitbox). */
    @Override
    public float getAgeScale() {
        return isBaby() ? 0.5f : super.getAgeScale();
    }

    /** -grow_up_ticks, so spawn-egg and summoned babies grow up as bred ones do. */
    @Override
    protected int getBabyStartAge() {
        return -24000;
    }

    /** The taming step of a right click: the taming food on a wild mob. Null passes on. */
    private InteractionResult tamingInteract(Player player, InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        if (!isTame()) {
            if (!TAMING_FOOD.test(stack)) {
                return null;
            }
            if (!(level() instanceof ServerLevel level)) {
                return InteractionResult.SUCCESS;
            }
            stack.consume(1, player);
            if (getRandom().nextFloat() < 1.0f) {
                tameWithFood(level, player);
            } else {
                level.broadcastEntityEvent(this, (byte) 6); // smoke
            }
            return InteractionResult.SUCCESS_SERVER;
        }
        return null;
    }

    /** A wolf's taming: the owner, tamed_health (healed to full), hearts. */
    private void tameWithFood(ServerLevel level, Player player) {
        tame(player);
        applyTamedHealth();
        getNavigation().stop();
        setTarget(null);
        level.broadcastEntityEvent(this, (byte) 7); // hearts
    }

    /** Asked by the owner target goals: never the owner, another pet of the same owner, or a player the owner may not hurt (a wolf's rule). */
    @Override
    public boolean wantsToAttack(LivingEntity target, LivingEntity owner) {
        if (!super.wantsToAttack(target, owner) || target == owner) {
            return false;
        }
        if (target instanceof TamableAnimal pet && pet.isTame() && pet.getOwner() == owner) {
            return false;
        }
        return !(target instanceof Player targetPlayer && owner instanceof Player ownerPlayer && !ownerPlayer.canHarmPlayer(targetPlayer));
    }

    /** A tamed mob is kept. */
    @Override
    public boolean requiresCustomPersistence() {
        return super.requiresCustomPersistence() || isTame();
    }

    /** msm_main loops walk while moving and idle otherwise; the other controllers play animations on request. */
    @Override
    public void registerControllers(AnimatableManager.ControllerRegistrar controllers) {
        RawAnimation idle = null;
        RawAnimation walk = null;
        AnimationController<TbTameFirstEntity> main = new AnimationController<>("msm_main", 0, test -> {
            RawAnimation loop = test.isMoving() && walk != null ? walk : idle;
            return loop == null ? PlayState.STOP : test.setAndContinue(loop);
        });
        controllers.add(main);
        AnimationController<TbTameFirstEntity> triggered = new AnimationController<>("msm_triggered", 0, test -> PlayState.STOP);
        controllers.add(triggered);
    }

    @Override
    public AnimatableInstanceCache getAnimatableInstanceCache() {
        return cache;
    }
}
